// Des: Arm a probe from its type + spec string
// Flo: check type > parse spec > build Prob or error
// I/O: type + spec text > Prob or ArmzErro
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const spawn = @import("spawn"); const netz = std.Io.net;
const evprobbase = @import("ev-prob-base.zig"); const ArmzErro = evprobbase.ArmzErro; const CF = evprobbase.CF; const Cond = evprobbase.Cond; const Kind = evprobbase.Kind; const duraPars = evprobbase.duraPars; const sizePars = evprobbase.sizePars; const evprobtype = @import("ev-prob-type.zig"); const Prob = evprobtype.Prob;
pub fn probTypeChec(typz: []const u8) bool { const allz = [_][]const u8{ "live", "disk", "mail", "idle", "powe", "proc", "tcpr", "webs" }; for (allz) |kind| if (std.mem.eql(u8, kind, typz)) return true; return false; }
pub fn probArmz(typz: []const u8, sche: ?[]const u8) ArmzErro!Prob { if (std.mem.eql(u8, typz, "mail")) { return .{ .kind = .emai, .unwi = true, .unwi_whyz = "needs IMAP credentials; auto-task holds none by design", .poll_msec = CF.poll_slow_msec }; } const rawz = sche orelse return ArmzErro.NeedsSpec; const spec = std.mem.trim(u8, rawz, " \t"); if (spec.len == 0) return ArmzErro.NeedsSpec; if (std.mem.eql(u8, typz, "tcpr")) return tcpzArmz(spec); if (std.mem.eql(u8, typz, "webs")) return webzArmz(spec); if (std.mem.eql(u8, typz, "disk")) return diskArmz(spec); if (std.mem.eql(u8, typz, "proc")) return nameArmz(.proc, spec); if (std.mem.eql(u8, typz, "live")) return nameArmz(.aliv, spec); if (std.mem.eql(u8, typz, "idle")) return idleArmz(spec); if (std.mem.eql(u8, typz, "powe")) return poweArmz(spec); return ArmzErro.NotProbeType; }
fn tcpzArmz(spec: []const u8) ArmzErro!Prob { const colo = std.mem.lastIndexOfScalar(u8, spec, ':'); if (colo == null) { const port = std.fmt.parseInt(u16, spec, 10) catch return ArmzErro.BadHost; if (port == 0) return ArmzErro.BadPort; return .{ .kind = .tcpz, .host = "127.0.0.1", .port = port, .poll_msec = CF.poll_slow_msec }; } const host_rawz = std.mem.trim(u8, spec[0..colo.?], " \t"); const port_rawz = std.mem.trim(u8, spec[colo.? + 1 ..], " \t"); const port = std.fmt.parseInt(u16, port_rawz, 10) catch return ArmzErro.BadPort; if (port == 0) return ArmzErro.BadPort; const host = std.mem.trim(u8, std.mem.trim(u8, host_rawz, "[]"), " \t"); if (host.len == 0) return ArmzErro.BadHost; return .{ .kind = .tcpz, .host = host, .port = port, .poll_msec = CF.poll_slow_msec }; }
fn webzArmz(spec_inzz: []const u8) ArmzErro!Prob { var spec = spec_inzz; var tlsz = false; if (std.ascii.startsWithIgnoreCase(spec, "https://")) { tlsz = true; spec = spec["https://".len..]; } else if (std.ascii.startsWithIgnoreCase(spec, "http://")) { spec = spec["http://".len..]; } if (tlsz) return ArmzErro.BadUrl; if (spec.len == 0) return ArmzErro.BadUrl; const slas = std.mem.indexOfScalar(u8, spec, '/'); const auth = if (slas) |indx| spec[0..indx] else spec; const path = if (slas) |indx| spec[indx..] else "/"; if (auth.len == 0) return ArmzErro.BadUrl; var host = auth; var port: u16 = 80; if (std.mem.lastIndexOfScalar(u8, auth, ':')) |colo| { const port_rawz = auth[colo + 1 ..]; port = std.fmt.parseInt(u16, port_rawz, 10) catch return ArmzErro.BadPort; if (port == 0) return ArmzErro.BadPort; host = auth[0..colo]; } host = std.mem.trim(u8, std.mem.trim(u8, host, "[]"), " \t"); if (host.len == 0) return ArmzErro.BadUrl; return .{ .kind = .webz, .host = host, .port = port, .path = path, .urlz = spec_inzz, .poll_msec = CF.poll_slow_msec }; }
fn diskArmz(spec: []const u8) ArmzErro!Prob { const oper_indx = std.mem.indexOfAny(u8, spec, "<>") orelse return ArmzErro.BadSize; const path = std.mem.trim(u8, spec[0..oper_indx], " \t"); if (path.len == 0) return ArmzErro.NeedsSpec; const belo = spec[oper_indx] == '<'; const size_rawz = std.mem.trim(u8, spec[oper_indx + 1 ..], " \t"); const byte = sizePars(size_rawz) orelse return ArmzErro.BadSize; return .{ .kind = .disk, .path = path, .thre = byte, .belo = belo, .poll_msec = CF.poll_midz_msec }; }
fn nameArmz(kind: Kind, spec: []const u8) ArmzErro!Prob { if (std.mem.indexOfAny(u8, spec, "/\\") != null) return ArmzErro.BadProc; return .{ .kind = kind, .name = spec, .poll_msec = CF.poll_midz_msec }; }
fn idleArmz(spec: []const u8) ArmzErro!Prob { const msec = duraPars(spec) orelse return ArmzErro.BadDuration; return .{ .kind = .idle, .thre = msec, .poll_msec = CF.poll_fast_msec }; }
fn poweArmz(spec: []const u8) ArmzErro!Prob { if (std.ascii.eqlIgnoreCase(spec, "battery") or std.ascii.eqlIgnoreCase(spec, "unplug")) { return .{ .kind = .powe, .batt_onzz = true, .poll_msec = CF.poll_fast_msec }; } if (std.ascii.eqlIgnoreCase(spec, "ac") or std.ascii.eqlIgnoreCase(spec, "plugged") or std.ascii.eqlIgnoreCase(spec, "plug")) { return .{ .kind = .powe, .batt_onzz = false, .poll_msec = CF.poll_fast_msec }; } return ArmzErro.BadPowerSpec; }
